@using sv_eaca2909259e408fbd7797c3c188e441.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@using sv_eaca2909259e408fbd7797c3c188e441.Models

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Company" @onchange="e => UpdateField(() => Company = e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Title" @onchange="e => UpdateField(() => Title = e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateField(() => StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>
        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateField(() => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; })" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => UpdateField(() => EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            }
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(() => Description = e.Value?.ToString() ?? string.Empty)"></textarea>
    </div>
    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }

    private void UpdateField(Action update)
    {
        update();
        var entry = new WorkEntry(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
        OnChanged.InvokeAsync(entry);
    }
}

