@using sv_eaca2909259e408fbd7797c3c188e441.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@using sv_eaca2909259e408fbd7797c3c188e441.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator
        CurrentStep="currentStep"
        CompletedSteps="completedSteps"
        OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalInfo.FullName"
                Email="@personalInfo.Email"
                Phone="@personalInfo.Phone"
                Address="@personalInfo.Address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep
                References="references"
                OnNext="HandleReferencesNext"
                OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep
                Personal="personalInfo"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                OnEditSection="GoToStep"
                OnBack="() => GoToStep(3)"
                OnSubmit="HandleSubmit"
                IsSubmitting="isSubmitting"
                IsSubmitted="isSubmitted"
                ApplicationId="applicationId"
                ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkEntry> workEntries = new() { new("", "", DateTime.Today, null, "") };
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };
    private string coverLetter = "";

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                personalInfo,
                new WorkHistory(workEntries),
                references,
                coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.dimmed .step-circle {
    border-color: #ddd;
    background: #f8f9fa;
    color: #aaa;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
