+    resize: vertical;
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+/* Buttons */
+.step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-primary {
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    padding: 0.6rem 1.5rem;
+    border-radius: 4px;
+    font-size: 1rem;
+    cursor: pointer;
+}
+
+.btn-primary:hover {
+    background: #0b5ed7;
+}
+
+.btn-primary:disabled {
+    background: #6c757d;
+    cursor: not-allowed;
+}
+
+.btn-outline {
+    background: #fff;
+    color: #0d6efd;
+    border: 1px solid #0d6efd;
+    padding: 0.6rem 1.5rem;
+    border-radius: 4px;
+    font-size: 1rem;
+    cursor: pointer;
+}
+
+.btn-outline:hover {
+    background: #e7f1ff;
+}
+
+.btn-secondary {
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    padding: 0.5rem 1rem;
+    border-radius: 4px;
+    cursor: pointer;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #5c636a;
+}
+
+.btn-remove {
+    background: #dc3545;
+    color: #fff;
+    border: none;
+    padding: 0.4rem 0.8rem;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.btn-remove:hover {
+    background: #bb2d3b;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #0d6efd;
+    cursor: pointer;
+    font-size: 0.9rem;
+    text-decoration: underline;
+}
+
+.btn-link:hover {
+    color: #0b5ed7;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.1rem;
+}
+
+/* Validation */
+.validation-error {
+    background: #f8d7da;
+    color: #842029;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-bottom: 1rem;
+    border: 1px solid #f5c2c7;
+}
+
+.validating {
+    font-size: 0.85rem;
+    color: #6c757d;
+    font-style: italic;
+}
+
+/* Character Count */
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.3rem;
+}
+
+/* Work Entry Form */
+.work-entry-form {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+/* Reference Form */
+.reference-form {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.reference-form h4 {
+    margin-top: 0;
+    margin-bottom: 1rem;
+    color: #555;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.3rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #555;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-work-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    margin: 0;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.submission-confirmation h3 {
+    color: #198754;
+    font-size: 1.5rem;
+}
+
+.submission-confirmation p {
+    font-size: 1.1rem;
+    color: #555;
+}
